using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using QuietDread;
public static class CommanderLegacyChecks {
 public static void Run(string root){
  var lines=new List<string>();Action<bool,string> check=(ok,n)=>{if(!ok)throw new Exception("COMMANDER LEGACY: "+n);lines.Add("PASS "+n);};var d=Content.Load();
  Action<Campaign> complete=c=>{c.act=3;c.nodes.First(n=>n.act==3&&n.kind=="Boss").visited=true;c.status="won";};
  check(d.units.Where(p=>p.commander).Select(p=>p.id).OrderBy(x=>x).SequenceEqual(CommanderRewardCatalog.Load().tracks.Select(t=>t.commander).OrderBy(x=>x)),"every playable commander has exactly one reward track");
  foreach(var track in CommanderRewardCatalog.Load().tracks){
   check(CommanderRewardCatalog.Load().tracks.Where(t=>t.faction==track.faction).All(t=>t.rewards.Select(r=>r.unit).OrderBy(x=>x).SequenceEqual(track.rewards.Select(r=>r.unit).OrderBy(x=>x))),track.commander+" cannot bypass another track by treating its rewards as basic units");
   var p=new TrailProgression();string primary=TrailProgression.Primary(d,track.faction);if(primary!=track.commander)p.commanders.Add(new CommanderProgress{commander=primary,completions=2});
   var roster=d.F(track.faction).defaults.Where(id=>!d.P(id).commander).ToList();roster.Insert(0,track.commander);
   check(p.CommanderWins(track.commander)==0,track.commander+" starts with independent zero wins");
   check(track.rewards.Count==5&&track.rewards.Select(r=>r.unit).Distinct().Count()==5&&track.rewards.All(r=>d.P(r.unit).faction==track.faction),track.commander+" five valid personal unit rewards");
   check(track.rewards.All(r=>!p.Allows(d,r.unit,track.commander)),track.commander+" rewards locked initially");
   for(int wins=1;wins<=10;wins++){var c=Campaign.Create(d,"trail",track.faction,roster,"normal",42,p);complete(c);check(p.Record(c)&&!p.Record(c),track.commander+" victory "+wins+" counted once");check(track.rewards.All(r=>p.Allows(d,r.unit,track.commander)==(wins>=r.wins)),track.commander+" milestone gating "+wins);check(!string.IsNullOrEmpty(TrailProgression.RewardText(d,track.commander,wins)),track.commander+" milestone has an effect "+wins);}
   check(p.CommanderWins(track.commander)==10,track.commander+" ten personal victories");
  }
  var progress=new TrailProgression();for(int i=0;i<10;i++){var c=Campaign.Create(d,"trail","vermin",d.F("vermin").defaults.ToList(),"normal",42,progress);complete(c);progress.Record(c);}
  check(progress.CanSelect(d,"seraphyx")&&progress.CommanderWins("seraphyx")==0,"discovered commander starts with no inherited wins");
  foreach(string reward in new[]{"gore_maiden","vermin_titan"})check(progress.Allows(d,reward,"marshal")&&!progress.Allows(d,reward,"seraphyx"),reward+" belongs only to its earning commander");
  var conquest=Campaign.Create(d,"conquest","vermin",d.F("vermin").defaults.ToList(),"normal",42,progress);check(conquest.gold==400,"owner gets starting supply benefit");conquest.gold=10000;check(conquest.RaiseArmy("seraphyx"),"discovered commander can lead a separate army");check(conquest.CommanderFor(conquest.Army)=="seraphyx"&&conquest.RecruitError("gore_maiden")!=null,"second Conquest army cannot use first commander's reward");
  var soldier=conquest.Army.units[0];check(conquest.TrainingCost(soldier)==50,"new commander does not inherit training charter");conquest.selectedArmy=1;check(conquest.Recruit("gore_maiden")&&conquest.TrainingCost(conquest.Army.units[0])==40,"earning commander's army retains recruitment and training rewards");
  var alternate=d.F("vermin").defaults.Where(id=>!d.P(id).commander).ToList();alternate.Insert(0,"seraphyx");alternate.Add("vermin_titan");var start=Campaign.Create(d,"trail","vermin",alternate,"normal",42,progress);check(start.gold==160&&start.Army.units.Count==3&&!start.Army.units.Any(v=>d.P(v.type).titan),"alternate commander gets no supply or titan bypass");
  var owned=Campaign.Create(d,"trail","vermin",d.F("vermin").defaults.ToList(),"normal",42,progress);check(owned.gold==210,"owner's new Trail gets supply warrant");var u=owned.Army.units[0];u.hp=1;owned.Heal(.5f);check(u.hp==1+(int)(d.P(u.type).hp*.6f),"personal surgeons improve recovery");owned.Visit(owned.nodes.First(owned.Available));var battle=owned.MakeBattle();battle.finished=true;battle.winner=0;owned.Settle(battle);check(owned.Army.units.All(v=>v.xp==3),"personal veteran command grants one additional victory XP");
  var old=new TrailProgression{version=1,factions=new List<FactionProgress>{new FactionProgress{faction="vermin",completions=10}},unlockedIds=new List<string>{"gore_maiden","seraphyx","vermin_titan"},completedRuns=new List<string>{"old-run"}};old.Migrate(d);check(old.version==2&&old.CommanderWins("marshal")==10&&old.CommanderWins("seraphyx")==0&&old.completedRuns.Contains("old-run"),"legacy ownership migration retains counts and deduplication");check(old.Allows(d,"vermin_titan","marshal")&&!old.Allows(d,"vermin_titan","seraphyx")&&!string.IsNullOrEmpty(old.migrationNote),"migration reports primary-commander assignment without global access");
  string dir=Path.Combine(root,"Temp/CommanderLegacyChecks-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);string path=Path.Combine(dir,"campaign.json");
  var original=Campaign.Create(d,"conquest","vermin",d.F("vermin").defaults.ToList());var save=new SaveGame{campaign=original};CampaignStorage.Write(path,save,d);original.gold=222;CampaignStorage.Write(path,save,d);bool recovered;check(CampaignStorage.Load(path,d,out recovered).campaign.gold==222&&!recovered,"valid primary is preferred");File.WriteAllText(path,"truncated {");var restored=CampaignStorage.Load(path,d,out recovered);check(recovered&&restored.campaign.gold==350,"damaged primary restores prior backup");CampaignStorage.Write(path,restored,d);check(Directory.GetFiles(dir,"*.damaged-*").Length==1&&CampaignStorage.Parse(File.ReadAllText(path+".bak"),d).campaign.gold==350,"recovery preserves damaged primary and good backup");File.Delete(path);check(CampaignStorage.Load(path,d,out recovered)!=null&&recovered,"missing primary recovers from backup");File.WriteAllText(path,"{\"version\":99,\"campaign\":{}}");bool future=false;try{CampaignStorage.Load(path,d,out recovered);}catch(NotSupportedException){future=true;}check(future&&File.ReadAllText(path).Contains("99"),"future save is rejected without silently reverting or overwriting");File.WriteAllText(path,"{}");File.WriteAllText(path+".bak","{}");bool failed=false;try{CampaignStorage.Load(path,d,out recovered);}catch(IOException){failed=true;}check(failed&&File.ReadAllText(path)=="{}","two invalid saves fail safely");
  string pp=Path.Combine(dir,"progress.json");progress.Save(pp);var loaded=TrailProgression.Load(pp);check(loaded.CommanderWins("marshal")==10&&!loaded.Allows(d,"vermin_titan","seraphyx"),"commander ownership persists across save/load");
  progress.Save(pp);File.WriteAllText(pp,"broken");var repaired=TrailProgression.Load(pp);check(repaired.recoveredFromBackup,"progress backup recovery is reported");repaired.Save(pp);check(TrailProgression.Load(pp+".bak").CommanderWins("marshal")==10,"writing recovered progress preserves valid backup");
  var active=Campaign.Create(d,"trail","vermin",d.F("vermin").defaults.ToList());active.Visit(active.nodes.First(active.Available));var activeBattle=active.MakeBattle();var roundtrip=CampaignStorage.Parse(JsonUtility.ToJson(new SaveGame{campaign=active,battle=activeBattle}),d);check(roundtrip.battle!=null&&roundtrip.battle.campaignBattleId==active.pendingId,"active tactical battle survives storage validation");
  File.WriteAllText(Path.Combine(root,"Documentation/COMMANDER-LEGACY-RESULTS.txt"),lines.Count+" commander ownership, reward and recovery checks passed\n"+string.Join("\n",lines));
 }
}
